// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/healthz", wrapper.Health)
	m.HandleFunc("GET "+options.BaseURL+"/readyz", wrapper.Ready)
	m.HandleFunc("GET "+options.BaseURL+"/v1/admin/catalog", wrapper.ReadAdminCatalog)
	m.HandleFunc("POST "+options.BaseURL+"/v1/admin/invocations/{invocationId}/reconcile", wrapper.ReconcileCharge)
	m.HandleFunc("GET "+options.BaseURL+"/v1/admin/ledger", wrapper.GetLedger)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/admin/models/{modelId}", wrapper.PutModel)
	m.HandleFunc("GET "+options.BaseURL+"/v1/admin/prices/{modelId}", wrapper.GetPriceBook)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/admin/profiles/{profileId}", wrapper.PutProfile)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/admin/providers/{providerId}", wrapper.PutProvider)
	m.HandleFunc("POST "+options.BaseURL+"/v1/admin/providers/{providerId}/credentials", wrapper.PutCredential)
	m.HandleFunc("POST "+options.BaseURL+"/v1/admin/providers/{providerId}/credentials/rotate", wrapper.RotateCredential)
	m.HandleFunc("POST "+options.BaseURL+"/v1/barriers", wrapper.AcquireBarrier)
	m.HandleFunc("POST "+options.BaseURL+"/v1/barriers/{barrierId}:release", wrapper.ReleaseBarrier)
	m.HandleFunc("GET "+options.BaseURL+"/v1/budget-policy", wrapper.ReadFeeBudgetPolicy)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/budget-policy", wrapper.PutFeeBudgetPolicy)
	m.HandleFunc("POST "+options.BaseURL+"/v1/catalog:refresh", wrapper.RefreshModelCatalog)
	m.HandleFunc("POST "+options.BaseURL+"/v1/cost-quotes", wrapper.QuoteCost)
	m.HandleFunc("POST "+options.BaseURL+"/v1/inferences", wrapper.CreateInference)
	m.HandleFunc("GET "+options.BaseURL+"/v1/inferences/{invocationId}", wrapper.ReadInference)
	m.HandleFunc("POST "+options.BaseURL+"/v1/inferences/{invocationId}/cancel", wrapper.CancelInference)
	m.HandleFunc("GET "+options.BaseURL+"/v1/inferences/{invocationId}/events", wrapper.ResumeInference)
	m.HandleFunc("GET "+options.BaseURL+"/v1/models", wrapper.ReadModels)
	m.HandleFunc("GET "+options.BaseURL+"/v1/profiles", wrapper.ReadProfiles)
	m.HandleFunc("POST "+options.BaseURL+"/v1/providers/{providerId}:probe", wrapper.CreateConnectionProbe)
	m.HandleFunc("POST "+options.BaseURL+"/v1/snapshots:discard", wrapper.DiscardSnapshot)
	m.HandleFunc("POST "+options.BaseURL+"/v1/snapshots:export", wrapper.ExportSnapshot)
	m.HandleFunc("POST "+options.BaseURL+"/v1/snapshots:stage", wrapper.StageSnapshot)
	m.HandleFunc("GET "+options.BaseURL+"/v1/task-assignments", wrapper.ReadTaskAssignments)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/task-assignments/{taskId}", wrapper.PutTaskAssignment)
	m.HandleFunc("POST "+options.BaseURL+"/v1/task-availability:read", wrapper.ReadTaskAvailability)
	m.HandleFunc("GET "+options.BaseURL+"/v1/usage", wrapper.QueryUsage)

	return m
}

